import numpy as np

with open('train.json') as f:
    train = json.load(f)
with open('dev_requests.json') as f:
    dev = json.load(f)

print("Train keys:", sorted(train.keys()))
for k, v in list(train.items())[:2]:
    print(f"Train[{k}] type: {type(v)}")
    if isinstance(v, dict):
        print(f"  keys: {v.keys()}")
        for sk, sv in v.items():
            if isinstance(sv, list):
                print(f"  {sk}: list of len {len(sv)}, first elem: {sv[0]}")
            else:
                print(f"  {sk}: {sv}")
    elif isinstance(v, list):
        print(f"  list of len {len(v)}, first elem: {v[0]}")

print("\nDev keys:", dev.keys())
for k in dev:
    print(f"Dev[{k}] type: {type(dev[k])}, len: {len(dev[k])}")
    if isinstance(dev[k], list) and len(dev[k]) > 0:
        print(f"  first elem keys: {dev[k][0].keys()}")
        for ek, ev in dev[k][0].items():
            if isinstance(ev, list):
                print(f"    {ek}: list of len {len(ev)}, first: {ev[0]}, last: {ev[-1]}")
            else:
                print(f"    {ek}: {ev}")
