for task in ['3A', '3B']:
    reqs = dev[task]
    null_counts = {}
    for req in reqs:
        for i, r in enumerate(req['history']):
            for k, v in r.items():
                if v is None:
                    null_counts.setdefault(k, set()).add(i)
    print(f"Dev {task} null indices by field:", {k: sorted(list(v)) for k, v in null_counts.items()})
